class Solution { public: int kthLargestValue(vector<vector<int>>& matrix,int k){int rows=matrix.size(),cols=matrix[0].size();vector<vector<int>> prefix(rows+1,vector<int>(cols+1));vector<int> values;for(int row=0;row<rows;++row)for(int col=0;col<cols;++col){prefix[row+1][col+1]=matrix[row][col]^prefix[row][col+1]^prefix[row+1][col]^prefix[row][col];values.push_back(prefix[row+1][col+1]);}nth_element(values.begin(),values.end()-k,values.end());return values[values.size()-k];} };
